sys_script_include.script:
function GetReferenceQualifierSubdivisionsByCountry(vCountry)
{
	var GetCountryRecord = x_snc_devtools.GetCountryRecord;
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var GetStringValue = x_snc_devtools.GetStringValue;

	var grCountry = GetCountryRecord(vCountry);
	if (IsValidRecord(grCountry) == false)
	{
		return '';
	}

	var aSubdivisionSysIds = [];

	var grSubdivisions = new GlideRecord('x_snc_geodata_country_subdivision');
	grSubdivisions.addQuery('country','=',grCountry.sys_id);
	grSubdivisions.orderBy('name');
	grSubdivisions.query();
	while (grSubdivisions.next())
	{
		aSubdivisionSysIds.push(GetStringValue(grSubdivisions.sys_id));
	}

	var strRefQual = '';
	for (var nSubdivision = 0; nSubdivision < aSubdivisionSysIds.length; nSubdivision++)
	{
		if (strRefQual != '')
		{
			strRefQual += '^OR';
		}
		strRefQual += 'sys_id=' + aSubdivisionSysIds[nSubdivision];
	}

	return strRefQual;
}
